CREATE SEQUENCE refunds_id_seq AS BIGINT;
CREATE TABLE refunds (
  id NUMERIC(20,0) DEFAULT nextval('refunds_id_seq') CHECK (id BETWEEN 0 AND 18446744073709551615) NOT NULL ,
  prepayment_id NUMERIC(20,0) CHECK (prepayment_id BETWEEN 0 AND 18446744073709551615) NOT NULL,
  order_id NUMERIC(20,0) CHECK (order_id BETWEEN 0 AND 18446744073709551615) NULL,
  out_refund_no BYTEA CHECK (octet_length(out_refund_no) <= 64) NOT NULL,
  idempotency_key_hash BYTEA CHECK (octet_length(idempotency_key_hash) = 32) NOT NULL,
  amount_cents NUMERIC(20,0) CHECK (amount_cents BETWEEN 0 AND 18446744073709551615) NOT NULL,
  currency CHAR(3) NOT NULL,
  reason_code VARCHAR(64) NOT NULL,
  requested_by_user_id NUMERIC(20,0) CHECK (requested_by_user_id BETWEEN 0 AND 18446744073709551615) NULL,
  requested_by_account_id NUMERIC(20,0) CHECK (requested_by_account_id BETWEEN 0 AND 18446744073709551615) NULL,
  provider_request_json JSONB NOT NULL,
  provider_request_digest BYTEA CHECK (octet_length(provider_request_digest) = 32) NOT NULL,
  provider_state TEXT CHECK (provider_state IN ('READY','CREATE_CLAIMED','CREATE_UNKNOWN','PROCESSING','SUCCESS','CLOSED')) NOT NULL,
  create_attempted_at TIMESTAMPTZ(6) NULL,
  provider_refund_id BYTEA CHECK (octet_length(provider_refund_id) <= 128) NULL,
  materialization_state TEXT CHECK (materialization_state IN ('AWAITING_PROVIDER','APPLIED','PENDING_MANUAL')) NOT NULL,
  pending_reason_code VARCHAR(64) NULL,
  materialized_at TIMESTAMPTZ(6) NULL,
  lease_kind TEXT CHECK (lease_kind IN ('CREATE','QUERY')) NULL,
  lease_owner BYTEA CHECK (octet_length(lease_owner) = 16) NULL,
  lease_expires_at TIMESTAMPTZ(6) NULL,
  record_version NUMERIC(20,0) CHECK (record_version BETWEEN 0 AND 18446744073709551615) NOT NULL DEFAULT 1,
  next_query_at TIMESTAMPTZ(6) NULL,
  created_at TIMESTAMPTZ(6) NOT NULL,
  updated_at TIMESTAMPTZ(6) NOT NULL,
  PRIMARY KEY (id),
  CONSTRAINT uq_refunds_prepayment UNIQUE (prepayment_id),
  CONSTRAINT uq_refunds_order UNIQUE (order_id),
  CONSTRAINT uq_refunds_out_refund_no UNIQUE (out_refund_no),
  CONSTRAINT fk_refunds_prepayment FOREIGN KEY (prepayment_id) REFERENCES prepayments (id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  CONSTRAINT fk_refunds_order FOREIGN KEY (order_id) REFERENCES orders (id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  CONSTRAINT fk_refunds_requested_user FOREIGN KEY (requested_by_user_id) REFERENCES miniprogram_users (id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  CONSTRAINT fk_refunds_requested_account FOREIGN KEY (requested_by_account_id) REFERENCES merchant_accounts (id) ON UPDATE RESTRICT ON DELETE RESTRICT,
  CONSTRAINT chk_refunds_immutable CHECK (OCTET_LENGTH(out_refund_no) BETWEEN 1 AND 64 AND amount_cents>0 AND currency='CNY' AND CHAR_LENGTH(TRIM(reason_code))>0 AND ((requested_by_user_id IS NOT NULL AND requested_by_account_id IS NULL) OR (requested_by_user_id IS NULL AND requested_by_account_id IS NOT NULL)) AND jsonb_typeof(provider_request_json)='object'),
  CONSTRAINT chk_refunds_lease_group CHECK ((lease_kind IS NULL AND lease_owner IS NULL AND lease_expires_at IS NULL) OR (lease_kind IS NOT NULL AND lease_owner IS NOT NULL AND lease_expires_at IS NOT NULL)),
  CONSTRAINT chk_refunds_provider_state CHECK ((provider_state='READY' AND create_attempted_at IS NULL AND provider_refund_id IS NULL AND lease_kind IS NULL) OR (provider_state='CREATE_CLAIMED' AND create_attempted_at IS NOT NULL AND provider_refund_id IS NULL AND lease_kind='CREATE') OR (provider_state='CREATE_UNKNOWN' AND create_attempted_at IS NOT NULL AND provider_refund_id IS NULL AND (lease_kind IS NULL OR lease_kind='QUERY')) OR (provider_state IN ('PROCESSING','SUCCESS','CLOSED') AND create_attempted_at IS NOT NULL AND provider_refund_id IS NOT NULL AND (lease_kind IS NULL OR lease_kind='QUERY'))),
  CONSTRAINT chk_refunds_materialization CHECK ((materialization_state='AWAITING_PROVIDER' AND pending_reason_code IS NULL AND materialized_at IS NULL) OR (materialization_state='APPLIED' AND pending_reason_code IS NULL AND materialized_at IS NOT NULL) OR (materialization_state='PENDING_MANUAL' AND pending_reason_code IS NOT NULL AND CHAR_LENGTH(TRIM(pending_reason_code))>0 AND materialized_at IS NULL)),
  CONSTRAINT chk_refunds_record_version CHECK (record_version>0)
);
ALTER SEQUENCE refunds_id_seq OWNED BY refunds.id;
